/* Real Chromium against production bundle; synthetic examples generated by real APIs. */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),output=process.argv[2],fixturePath=process.argv[3];
if(!output||fs.existsSync(output)||!fixturePath)throw Error('NEW output path and fixture required');
const fixture=JSON.parse(fs.readFileSync(fixturePath));const {chromium}=require(process.env.PLAYWRIGHT_MODULE_DIR+'/playwright');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const started=performance.now(),results=[],errors=[],external=[],calls=[];
 const browser=await chromium.launch({headless:true,executablePath:process.env.BROWSER_EXECUTABLE});const context=await browser.newContext({viewport:{width:1440,height:1050}});const page=await context.newPage();page.setDefaultTimeout(6500);page.on('pageerror',e=>errors.push(e.message));
 let control={};const first=fixture.datasets[0],pdf=fixture.datasets[1],mainCandidate=first.responses['/candidates'].candidates[0];
 const safeJob=(ds,state)=>({...ds.job,state,events:state==='completed'?ds.job.events:[],attempt:state==='queued'?0:1,...(state==='failed'?{error_code:'workflow_internal_failure',error_category:'RETRYABLE'}:{error_code:null,error_category:null})});
 await page.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());
  if(u.origin!=='http://127.0.0.1:4173'){external.push(u.origin);return route.abort();}
  const reply=(body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
  if(u.pathname.startsWith('/api/')){calls.push({path:u.pathname,method:req.method(),headers:req.headers()});
   if(u.pathname==='/api/auth/status'){await delay(control.authDelay||0);return reply({provider_available:!control.unavailable,remote_enabled:control.remoteFlag??false});}
   if(u.pathname==='/api/auth/me')return control.anonymous?reply({},401):reply({user_id:'synthetic-reviewer',institution_id:'A',institution_name:'합성 연구지원기관',role:control.role||'manager',institution_admin:true,csrf_token:'synthetic-csrf'});
   if(u.pathname==='/api/documents'){const docs=structuredClone(fixture.documents);if(control.foreignList)docs[0].institution_id='B';if(control.deregister)docs[0].registered=false;if(control.inactive)docs[0].active=false;return reply(docs);}
   const match=u.pathname.match(/^\/api\/documents\/([^/]+)\/versions\/([^/]+)(.*)$/);if(!match)return reply({},404);
   const ds=fixture.datasets.find(x=>x.document.document_id===match[1]&&x.document.id===match[2]);if(!ds){const doc=fixture.documents.find(d=>d.document_id===match[1]&&d.id===match[2]);return reply(doc||{},doc?200:404);}
   const tail=match[3];if(!tail){if(control.deregister)return reply({},404);return reply({...ds.document,active:control.inactive?false:true});}
   if(tail==='/original'){await delay(control.pdfDelay||0);return route.fulfill({status:200,contentType:'application/pdf',body:Buffer.from(ds.original_pdf_base64,'base64')});}
   if(tail.includes('/chunks/')){if(control.resolveDelay)await delay(control.resolveDelay);if(control.resolveMissing)return reply({},404);if(control.resolveNetwork)return route.abort();assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');const ref=req.postDataJSON();let data=structuredClone(ds.resolved[ref.chunk_id]);if(control.badResolve)data.evidence.organization_id='B';return reply(data);}
   if(!tail.startsWith('/workflow'))return reply({},404);
   if(control.forbiddenAll)return reply({},403);
   const suffix=tail.slice('/workflow'.length);if(suffix==='/jobs'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');assert.deepEqual(req.postDataJSON(),{});control.posts=(control.posts||0)+1;await delay(control.submitDelay||0);return reply(safeJob(ds,control.enqueueFailed?'failed':'queued'),202);}
   if(suffix.endsWith('/retry')){control.retries=(control.retries||0)+1;return reply(safeJob(ds,'queued'),202);}
   if(suffix.endsWith('/cancel')){control.cancels=(control.cancels||0)+1;return reply(safeJob(ds,'cancelled'));}
   if(suffix.startsWith('/jobs/')){control.polls=(control.polls||0)+1;return reply(safeJob(ds,control.neverComplete?'processing':control.polls<2?'processing':'completed'));}
   if(suffix==='/candidates'&&control.workflowError){if(control.workflowError==='network')return route.abort();return reply({},control.workflowError);}
   if(control.evidenceMissing&&suffix.endsWith('/evidence'))return reply({},404);
   if(control.evidenceDelay&&suffix.endsWith('/evidence'))await delay(control.evidenceDelay);
   if(control.late&&ds===first&&suffix==='/candidates')await delay(1200);
   let data=structuredClone(ds.responses[suffix+u.search]||ds.responses[suffix]);if(!data)return reply({},404);
   if(control.bigGraph&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence')){const c=data.candidates[0];c.steps=[...c.steps,...Array.from({length:96},(_,i)=>({...structuredClone(c.steps[i%4]),id:'stress_'+i}))];}
   if(control.empty&&suffix==='/candidates')data.candidates=[];
   if(control.unsafe)data.semantic_verification='VERIFIED';
   if(control.mixedGeneration&&suffix.startsWith('/form-links'))data.generation_id='another-generation';
   if(control.multipleEvidence&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].steps[0].actions.push(structuredClone(data.candidates[0].steps[1].label));
   if(control.foreignEvidence&&suffix.endsWith('/evidence'))data.evidence_refs[0].organization_id='B';
   if(control.unrenderable&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].edges[0].target='unknown-step';
   try{return await reply(data);}catch{return;}
  }
  const dist=path.join(root,'apps/web/dist'),file=path.resolve(dist,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(u.pathname==='/favicon.ico')return route.fulfill({status:204,body:''});if(!file.startsWith(dist+path.sep)||!fs.existsSync(file))return route.abort();return route.fulfill({body:fs.readFileSync(file),contentType:file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html'});
 });
 let bootId=0;
 async function boot(options={},ready=true){control={...options};await page.setViewportSize({width:1440,height:1050});await page.goto('http://127.0.0.1:4173/?case='+(++bootId)+'#/workflows');if(ready)await page.locator('.wf-original-quote').waitFor();}
 async function check(name,fn){try{await fn();results.push({name,status:'PASS'});console.log('PASS '+name);}catch(e){results.push({name,status:'FAIL',error:e.message});console.log('FAIL '+name+': '+e.message);}}
 async function step(index){await page.locator('.wf-map-node').nth(index).click();await page.locator('.wf-original-quote').filter({hasText:mainCandidate.steps[index].label.evidence[0].quote}).waitFor();}

 const captures=path.resolve(root,process.env.V02A_CAPTURE_DIR||'outputs/v02a/ui');
 async function home(options={}){control={...options};await page.setViewportSize({width:1440,height:1050});await page.goto('http://127.0.0.1:4173/?home='+(++bootId)+'#/home');await page.getByRole('heading',{name:'업무 홈',exact:true}).waitFor();if(!options.authDelay)await page.waitForTimeout(100);}
 async function confirmed(){await page.locator('.wf-map-node[aria-pressed=true] .wf-node-caption span').filter({hasText:'출처 확인'}).waitFor({state:'attached'});}
 async function capture(name){fs.mkdirSync(captures,{recursive:true});const file=path.join(captures,name);if(fs.existsSync(file))throw Error('new capture path required');await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:file,fullPage:true});}
 try{
 await check('manager home offers actual registration and workflow review without fake counts',async()=>{await home();await page.getByText('문서 등록·조회 가능',{exact:true}).waitFor();await page.getByRole('link',{name:'문서 등록하러 가기',exact:true}).waitFor();await page.getByRole('link',{name:'업무절차 후보 검토',exact:true}).waitFor();const t=await page.locator('main').innerText();assert.doesNotMatch(t,/문서 등록 · 준비 중|원문 검토 화면은 준비 중/);assert.match(t,/최근 문서 조회가 연결되지 않았습니다/);assert.equal(await page.locator('main table,[role=progressbar]').count(),0);await capture('home-manager-desktop.png');});
 await check('reader home offers query and explains mutation limits',async()=>{await home({role:'reader'});await page.getByText('문서 조회 가능',{exact:true}).waitFor();assert.equal(await page.getByRole('link',{name:'문서 등록하러 가기',exact:true}).count(),0);assert.equal(await page.getByRole('link',{name:'업무절차 후보 검토',exact:true}).count(),0);assert.match(await page.locator('#home-upload-note').innerText(),/자료관리자/);await page.getByRole('link',{name:'문서 조회로 이동',exact:true}).click();await page.locator('#document-file').waitFor();assert.equal(await page.locator('#document-file').isDisabled(),true);});
 await check('anonymous home distinguishes existing documents feature from login requirement',async()=>{await home({anonymous:true});await page.getByText('로그인 필요',{exact:true}).waitFor();await page.getByRole('link',{name:'로그인 상태 확인',exact:true}).click();await page.locator('#login-email').waitFor();assert.equal(await page.locator('.wf-map-node').count(),0);});
 await check('unavailable provider never means document feature is unimplemented',async()=>{await home({anonymous:true,unavailable:true});assert.match(await page.locator('main').innerText(),/문서 등록·조회 기능을 제공합니다/);await page.getByRole('link',{name:'로그인 상태 확인',exact:true}).click();await page.locator('#login-email:disabled').waitFor();});
 await check('loading role never claims manager capability',async()=>{await home({authDelay:500});assert.equal(await page.getByRole('link',{name:'문서 등록하러 가기',exact:true}).count(),0);await page.getByText('문서 등록·조회 가능',{exact:true}).waitFor();});
 await check('local login status and actual AI remain distinct from document capability',async()=>{await home();assert.match(await page.locator('.connection-notice').innerText(),/자료관리자/);assert.match(await page.locator('.connection-notice').innerText(),/Supabase 원격 로그인 미연결/);assert.match(await page.locator('main').innerText(),/실제 AI 미연결/);assert.doesNotMatch(await page.locator('.connection-notice').innerText(),/데이터 미연결/);});
 await check('remote setting display is based on existing status flag and makes no connectivity claim',async()=>{await home({remoteFlag:true});await page.getByText(/외부 로그인 설정 감지/).waitFor();assert.doesNotMatch(await page.locator('.connection-notice').innerText(),/Supabase 원격 로그인 미연결/);assert.match(await page.locator('.connection-notice').innerText(),/실제 원격 연결 검증 여부는 별도/);});
 await check('manager registration link enters existing form without submitting',async()=>{await home();await page.getByRole('link',{name:'문서 등록하러 가기',exact:true}).click();await page.locator('#document-file:not(:disabled)').waitFor();assert.equal(calls.filter(x=>x.method==='POST'&&x.path==='/api/documents').length,0);});
 await check('node stays unconfirmed until original source resolves',async()=>{await boot({resolveDelay:500},false);await page.getByText('원문 출처를 확인하고 있습니다.',{exact:true}).waitFor();assert.match(await page.locator('.wf-map-node[aria-pressed=true] .wf-node-caption').innerText(),/근거 확인 필요/);assert.equal(await page.locator('.wf-original-quote').count(),0);await confirmed();await page.locator('.wf-original-quote').waitFor();});
 await check('source-confirmed node and current evidence panel agree; semantic state remains pending',async()=>{await boot();await confirmed();assert.equal(await page.locator('.wf-evidence-pane .status-badge').filter({hasText:'출처 확인'}).count(),1);assert.match(await page.locator('.wf-evidence-pane').innerText(),/내용 검토 필요/);const trust=await page.locator('.wf-trust').innerText();assert.doesNotMatch(trust,/NOT_VERIFIED|NOT_REQUESTED/);assert.match(await page.locator('.wf-trust details').textContent(),/NOT_VERIFIED.*NOT_REQUESTED/);assert.equal(await page.getByRole('button',{name:/승인|공식 게시/}).count(),0);await capture('workflow-desktop.png');});
 await check('technical identifiers and flags live under explicit details',async()=>{await boot();await page.locator('.wf-anchor').waitFor({state:'attached'});assert.equal(await page.locator('.wf-anchor').isVisible(),false);assert.doesNotMatch(await page.locator('.wf-evidence-pane').innerText(),/EvidenceRef|NOT_VERIFIED|NOT_REQUESTED/);await page.locator('.wf-evidence-pane details').filter({has:page.getByText('출처 확인 상세',{exact:true})}).locator('summary').click();assert.match(await page.locator('.wf-evidence-pane').innerText(),/EvidenceRef.*NOT_VERIFIED/);});
 await check('multiple citations cannot promote a whole step after verifying only one',async()=>{await boot({multipleEvidence:true});await page.getByText('단계 근거 2개 중 1개 출처 확인',{exact:false}).waitFor();assert.match(await page.locator('.wf-map-node[aria-pressed=true] .wf-node-caption').innerText(),/근거 확인 필요/);await page.locator('.wf-evidence-picker button').nth(1).click();await confirmed();assert.match(await page.locator('.wf-evidence-pane').innerText(),/단계 근거 2개 중 2개 출처 확인/);});
 await check('reselecting the same citation does not hang in loading',async()=>{await boot();await confirmed();const n=calls.filter(x=>x.path.endsWith('/evidence/resolve')).length;await page.locator('.wf-evidence-picker button').first().click();await page.locator('.wf-original-quote').waitFor();await confirmed();assert.equal(calls.filter(x=>x.path.endsWith('/evidence/resolve')).length,n);});
 for(const option of ['badResolve','foreignEvidence','resolveNetwork'])await check(option+' never shows confirmed source or original',async()=>{await boot({[option]:true},false);await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);assert.equal(await page.locator('.wf-map-node[aria-pressed=true] .wf-node-caption span').filter({hasText:'출처 확인'}).count(),0);assert.match(await page.locator('[role=alert]').innerText(),/근거|출처/);});
 for(const option of ['evidenceMissing','resolveMissing'])await check(option+' explains missing source and clears stale candidate',async()=>{await boot({[option]:true},false);await page.getByText(/원문 근거를 찾을 수 없습니다/).waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);assert.equal(await page.locator('.wf-map-node').count(),0);});
 await check('step switch restarts source confirmation and preserves unselected warnings',async()=>{await boot({resolveDelay:250});await confirmed();await page.locator('.wf-map-node').nth(1).click();await page.getByText('원문 출처를 확인하고 있습니다.',{exact:true}).waitFor();assert.match(await page.locator('.wf-map-node[aria-pressed=true] .wf-node-caption').innerText(),/근거 확인 필요/);await confirmed();assert.match(await page.locator('.wf-map-node').first().locator('.wf-node-caption').innerText(),/근거 확인 필요/);});
 await check('late old-document resolution cannot confirm new document nodes',async()=>{await boot({resolveDelay:700},false);await page.getByText('원문 출처를 확인하고 있습니다.',{exact:true}).waitFor();await page.getByLabel('문서',{exact:true}).selectOption(pdf.document.document_id);await page.locator('.wf-original-quote').waitFor();await confirmed();await page.waitForTimeout(900);assert.match(await page.locator('.wf-evidence-meta').innerText(),/광물-접수.pdf/);});
 await check('unsafe semantic promotion is still rejected by unchanged API guards',async()=>{await boot({unsafe:true},false);await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.wf-map-node').count(),0);});
 await check('keyboard focus and mobile tabs still reach evidence',async()=>{await boot();await page.setViewportSize({width:375,height:812});await page.getByRole('button',{name:'단계 목록',exact:true}).click();const button=page.locator('.wf-step-list button').nth(1);await button.focus();await page.keyboard.press('Enter');await page.locator('.wf-original-quote').waitFor();await page.locator('.wf-evidence-pane .status-badge').filter({hasText:'출처 확인'}).waitFor();assert.equal(await page.evaluate(()=>document.activeElement.textContent),'원문 근거 확인');await capture('workflow-mobile-evidence.png');await page.getByRole('tab',{name:'지도·단계'}).click();await page.getByRole('button',{name:'지도',exact:true}).click();await confirmed();await capture('workflow-mobile-map.png');});
 await check('PC/mobile role copy reflows at 320/375/768/1440',async()=>{await home();for(const width of [320,375,768,1440]){await page.setViewportSize({width,height:812});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),String(width));}await page.setViewportSize({width:375,height:812});await capture('home-manager-mobile.png');await home({role:'reader'});await page.setViewportSize({width:375,height:812});await capture('home-reader-mobile.png');});
 await check('no new approval/activation UI, browser storage, exceptions or external traffic',async()=>{await boot();assert.equal(await page.getByRole('button',{name:/활성화|공식 게시|최종 승인/}).count(),0);assert.equal(await page.evaluate(()=>localStorage.length+sessionStorage.length),0);assert.deepEqual(errors,[]);assert.deepEqual(external,[]);});
 }finally{await browser.close();}
 const report={scope:'v0.2-A production Chromium; existing real-backend-generated synthetic DTO fixture via local response interception; not live-provider integration',results,counts:{PASS:results.filter(r=>r.status==='PASS').length,FAIL:results.filter(r=>r.status==='FAIL').length},seconds:(performance.now()-started)/1000,errors,external,actual_external_provider_calls:0,not_run:['real Supabase/LLM/embedding','screen reader','public deployment']};fs.writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));if(report.counts.FAIL)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
